const input = $input.first()?.json?.body || {};
const evidenceIds = input.evidence_ids || [];
const evidenceItems = input.evidence || [];

// Sources that require LLM interpretation
const unstructuredSources = ['email_reply', 'interview_transcript', 'community_thread', 'support_ticket', 'linkedin_message', 'call_notes'];
const structuredSources = ['outreach_pipeline', 'pilot_evidence', 'response_signals', 'metrics_export', 'analytics'];

const categorized = evidenceItems.map(ev => ({
  ...ev,
  needs_llm: unstructuredSources.includes(ev.source) || !ev.recommended_interpretation || ev.recommended_interpretation === 'Requires interpretation',
  evidence_id: ev.id || ev.evidence_id || ('ev-' + Date.now() + '-' + Math.random().toString(36).substr(2,6))
}));

const needsLLM = categorized.filter(e => e.needs_llm);
const canDeterministic = categorized.filter(e => !e.needs_llm);

console.log('Normalize Evidence: ' + needsLLM.length + ' need LLM, ' + canDeterministic.length + ' can use rules');

// Pass all items through with needs_llm flag
return categorized.length > 0 
  ? categorized.map(e => ({ json: e }))
  : [{ json: { evidence_ids: evidenceIds, needs_llm: false, message: 'No evidence items provided', source: 'unknown', recommended_interpretation: '' } }];

