// Apply deterministic normalization rules for structured sources
const item = $input.first().json;

const rules = {
  outreach_pipeline: { fits: ['MP', 'PC'], direction: item.magnitude > 0.5 ? 'positive' : 'neutral' },
  pilot_evidence: { fits: ['PC', 'CM'], direction: 'positive' },
  response_signals: { fits: ['MP', 'PC', 'CM'], direction: item.magnitude > 0.3 ? 'positive' : 'negative' },
  metrics_export: { fits: ['CM', 'MM'], direction: item.magnitude > 0.5 ? 'positive' : 'negative' },
  analytics: { fits: ['MM'], direction: item.magnitude > 0.5 ? 'positive' : 'neutral' }
};

const rule = rules[item.source] || { fits: ['MP'], direction: 'neutral' };

return [{ json: {
  ...item,
  fits_affected: item.fits_affected?.length > 0 ? item.fits_affected : rule.fits,
  direction: item.direction !== 'neutral' ? item.direction : rule.direction,
  magnitude: item.magnitude || 0.5,
  confidence: item.confidence || 0.7,
  recommended_interpretation: item.recommended_interpretation || 'Deterministic rule applied for ' + item.source,
  normalization_method: 'deterministic'
} }];

const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;
  let normalized = { ...data };

  // If this came from LLM, parse the LLM response
  if (data.choices?.[0]?.message?.content) {
    try {
      const llmResult = JSON.parse(data.choices[0].message.content);
      normalized = {
        ...data,
        fits_affected: llmResult.fits_affected || data.fits_affected || [],
        direction: llmResult.direction || data.direction || 'neutral',
        magnitude: llmResult.magnitude !== undefined ? llmResult.magnitude : (data.magnitude || 0.5),
        confidence: llmResult.confidence !== undefined ? llmResult.confidence : (data.confidence || 0.5),
        recommended_interpretation: llmResult.recommended_interpretation || data.recommended_interpretation || '',
        normalization_method: 'llm'
      };
    } catch(e) {
      normalized.normalization_method = 'llm_parse_error';
    }
  }

  output.push({ json: {
    evidence_id: normalized.evidence_id,
    timestamp: normalized.timestamp || new Date().toISOString(),
    source: normalized.source,
    source_reliability: normalized.source_reliability || 0.7,
    fits_affected: normalized.fits_affected || [],
    metric_or_claim: normalized.metric_or_claim || 'signal',
    direction: normalized.direction || 'neutral',
    magnitude: normalized.magnitude || 0.5,
    confidence: normalized.confidence || 0.5,
    linked_entity: normalized.linked_entity || null,
    quote_or_payload: normalized.quote_or_payload || normalized.raw_content || null,
    recommended_interpretation: normalized.recommended_interpretation || '',
    normalization_method: normalized.normalization_method || 'unknown',
    normalized_at: new Date().toISOString(),
    ready_for_db: true
  } });
}

return output.length > 0 ? output : [{ json: { message: 'No events normalized', count: 0 } }];

